    /// <summary><c>preset</c>: Expand presets in place.</summary>
    /// <remarks>URL names: <c>preset</c>, <c>pr</c>; arguments <c>names…</c>; default —. Milestone M1; scope pipeline.</remarks>
    public sealed record Preset : InfoOption
    {
        /// <summary>Expand presets in place.</summary>
        /// <remarks>URL names: <c>preset</c>, <c>pr</c>; arguments <c>names…</c>; default —. Milestone M1; scope pipeline.</remarks>
        /// <param name="name">preset name.</param>
        /// <param name="names">Repeated argument: name — preset name.</param>
        public Preset(string name, params string[] names)
            : base("preset", Args0(name, names))
        {
        }

        private static OptionArg[] Args0(string name, string[] names)
        {
            ArgumentNullException.ThrowIfNull(names);
            var args = new List<OptionArg>(1 + (names.Length * 1)) { name };
            foreach (var e in names)
            {
                args.Add(e);
            }

            return [.. args];
        }
    }

